#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Always run from the repo root so .env and schema paths resolve.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
ENV_FILE="$ROOT/.env"
SCHEMA_FILE="$ROOT/supabase/schema.sql"

banner "Birthday party · Supabase + GitHub Pages"

# ── 1. Party identity ─────────────────────────────────────────────────────
stage "Identidade da festa"
say "Nome e frase que aparecem na home. Podem mudar depois no .env."
ask VITE_PARTY_NAME "Nome da festa (ex.: Caio):"
ask VITE_PARTY_TAGLINE "Tagline (uma frase curta):"
[[ -n "${VITE_PARTY_NAME:-}" ]] || VITE_PARTY_NAME="Caio"
[[ -n "${VITE_PARTY_TAGLINE:-}" ]] || VITE_PARTY_TAGLINE="Vem celebrar comigo — escolhe uma música e manda uma foto pra decoração."
write_env VITE_PARTY_NAME "$VITE_PARTY_NAME"
write_env VITE_PARTY_TAGLINE "$VITE_PARTY_TAGLINE"

# ── 2. Supabase project ───────────────────────────────────────────────────
stage "Criar projeto Supabase"
say "Vamos criar o backend free (Postgres + Storage)."
open_url "https://supabase.com/dashboard"
step "Faça login (GitHub/Google/email)."
step "Clique New Project (ou Create a new project)."
step "Name: birthday-party (ou similar)."
step "Database Password: gere uma forte e guarde em um gerenciador — o app não usa essa senha."
step "Region: a mais perto de você (ex.: South America)."
step "Create new project e espere o provisionamento (~1–2 min)."
pause "Projeto pronto (dashboard do projeto aberto)?"

# ── 3. Schema SQL ─────────────────────────────────────────────────────────
stage "Rodar schema SQL"
say "Cria tabelas songs/photos, RLS e o bucket party-photos."
note "Arquivo local: $SCHEMA_FILE"
if command -v code >/dev/null 2>&1; then
  code "$SCHEMA_FILE" >/dev/null 2>&1 || true
  note "Abri o schema no editor (se o VS Code/Cursor estiver disponível)."
elif command -v wslview >/dev/null 2>&1; then
  wslview "$SCHEMA_FILE" >/dev/null 2>&1 || true
fi
open_url "https://supabase.com/dashboard/project/_/sql/new"
step "No canto superior do dashboard, confirme que o projeto birthday-party está selecionado."
step "Se a URL abriu em project/_ , abra SQL no menu esquerdo → New query."
step "Cole o conteúdo inteiro de supabase/schema.sql."
step "Clique Run (ou Ctrl/Cmd+Enter)."
step "Deve aparecer Success (sem erros vermelhos)."
pause "SQL rodou com sucesso?"

# ── 4. API credentials ────────────────────────────────────────────────────
stage "Credenciais Supabase (URL + key)"
say "URL do projeto e a chave pública do client (Publishable ou legacy anon)."
open_url "https://supabase.com/dashboard/project/_/settings/api-keys"
step "No projeto certo: Settings (engrenagem) → API Keys."
step "Alternativa: botão Connect no topo do dashboard → copie Project URL e a key do browser."
step "Project URL parece com https://xxxxxxxx.supabase.co"
ask VITE_SUPABASE_URL "Cole a Project URL:"
step "Copie a Publishable key (sb_publishable_...). Se só existir a legacy anon (JWT eyJ...), use essa."
warn "NÃO use a Secret / service_role — ela bypassa RLS."
ask_secret VITE_SUPABASE_ANON_KEY "Cole a Publishable ou anon key:"
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"

# ── 5. GitHub repo + push ─────────────────────────────────────────────────
stage "Repositório GitHub"
say "Publica o código em github.com para o Pages poder servir o site."
REPO_NAME="birthday-party"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "gh autenticado."
else
  warn "gh não está pronto. Vamos abrir o login; depois reabra este stage se precisar."
  open_url "https://github.com/login"
  step "No terminal, rode: gh auth login  (GitHub.com → HTTPS → login via browser)."
  pause "gh auth login concluído?"
fi

if confirm "Criar o repo público '$REPO_NAME' no GitHub e apontar o remote origin?"; then
  if git remote get-url origin >/dev/null 2>&1; then
    note "Remote origin já existe: $(git remote get-url origin)"
  elif command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    gh repo create "$REPO_NAME" --public --source=. --remote=origin
    note "Repo criado e remote origin configurado."
  else
    open_url "https://github.com/new"
    step "Repository name: $REPO_NAME · Public · NÃO marque 'Add a README'."
    step "Create repository, depois copie a URL HTTPS."
    ask REPO_URL "Cole a URL do repo (https://github.com/USER/birthday-party.git):"
    git remote add origin "$REPO_URL" 2>/dev/null || git remote set-url origin "$REPO_URL"
  fi
else
  note "Pulando criação do repo. Você pode fazer depois."
fi

if ! git rev-parse HEAD >/dev/null 2>&1; then
  if confirm "Ainda não há commit. Criar o commit inicial agora?"; then
    git add -A
    git status --short
    if confirm "Confirma git commit do que está staged?"; then
      git commit -m "$(cat <<'EOF'
feat: webapp de aniversário com playlist e fotos

EOF
)"
    fi
  fi
fi

if git remote get-url origin >/dev/null 2>&1; then
  if confirm "Fazer push de main para origin?"; then
    git branch -M main 2>/dev/null || true
    git push -u origin main
  else
    note "Push adiado."
  fi
else
  SKIPPED+=("git remote origin / primeiro push")
  warn "Sem remote origin — configure o repo e faça push depois."
fi

# ── 6. GitHub Pages source ────────────────────────────────────────────────
stage "GitHub Pages = GitHub Actions"
say "O workflow .github/workflows/deploy.yml publica o build."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 && git remote get-url origin >/dev/null 2>&1; then
  OWNER_REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
  if [[ -n "${OWNER_REPO:-}" ]]; then
    open_url "https://github.com/${OWNER_REPO}/settings/pages"
  else
    open_url "https://github.com/settings/pages"
  fi
else
  open_url "https://github.com"
  step "Abra o repo birthday-party → Settings → Pages."
fi
step "Build and deployment → Source: GitHub Actions (não 'Deploy from a branch')."
step "Salve se o UI pedir."
pause "Source = GitHub Actions?"

# ── 7. CI secrets & variables ─────────────────────────────────────────────
stage "Secrets e variables do Actions"
say "O deploy.yml lê secrets VITE_SUPABASE_* e vars VITE_PARTY_*."
if ! git remote get-url origin >/dev/null 2>&1; then
  SKIPPED+=("GitHub secrets/vars (sem remote)")
  warn "Sem remote — pule e rode o wizard de novo depois do push."
else
  set_secret VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
  set_secret VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"
  set_var VITE_PARTY_NAME "$VITE_PARTY_NAME"
  set_var VITE_PARTY_TAGLINE "$VITE_PARTY_TAGLINE"
  note "Se o set_secret falhou, em Settings → Secrets and variables → Actions cole os mesmos valores."
fi
pause "Secrets/vars ok (ou anotados para fazer à mão)?"

# ── 8. Smoke local ────────────────────────────────────────────────────────
stage "Smoke local"
say "Instala deps e confirma que o app sobe com o .env."
step "Vou rodar npm install neste diretório."
pause "Enter para npm install…"
npm install
note "Depois, em outro terminal: npm run dev"
note "Abra http://localhost:5173/birthday-party/"
note "Site em produção (após o Actions verde): https://<user>.github.io/birthday-party/"
if confirm "Disparar o workflow de deploy agora (gh workflow run)?"; then
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    gh workflow run "Deploy GitHub Pages" || warn "Não deu para disparar; um push em main também dispara."
  else
    warn "gh indisponível — push em main ou Actions → Run workflow."
  fi
fi

finish
note "Próximo: npm run dev · baixar fotos em Supabase → Storage → party-photos"
}

run_wizard "$@"; exit
